describe('Network Request Retry Button', () => {
  beforeEach(() => {
    cy.visit('/api/data');
  });

  it('should display retry button when network request times out and user clicks it', () => {
    // Setup: intercept the API call with a timeout
    cy.intercept('GET', '/api/data', {
      statusCode: 500,
      delay: 2000
    }).as('apiRequest');

    // First attempt: trigger the API call
    cy.get('[data-testid="fetch-data-button"]').click();

    // Verify error state is displayed
    cy.get('[data-testid="error-message"]').should('be.visible').should('contain', 'Failed to load data');

    // Verify retry button is visible
    cy.get('[data-testid="retry-button"]').should('be.visible');

    // Verify retry button has correct text
    cy.get('[data-testid="retry-button"]').should('contain', 'Retry');

    // Click retry button
    cy.get('[data-testid="retry-button"]').click();

    // Verify error message is cleared
    cy.get('[data-testid="error-message"]').should('not.exist');

    // Verify data is now loaded
    cy.get('[data-testid="data-table"]').should('be.visible');
    cy.get('[data-testid="data-row"]').should('have.length.greaterThan', 0);
  });

  it('should not display retry button when network request succeeds on first attempt', () => {
    // Setup: intercept the API call with a success response
    cy.intercept('GET', '/api/data', {
      statusCode: 200,
      body: {
        data: [
          { id: 1, name: 'Item 1' },
          { id: 2, name: 'Item 2' }
        ]
      }
    }).as('apiRequestSuccess');

    // First attempt: trigger the API call
    cy.get('[data-testid="fetch-data-button"]').click();

    // Verify success state is displayed
    cy.get('[data-testid="success-message"]').should('be.visible').should('contain', 'Data loaded successfully');

    // Verify retry button is not visible
    cy.get('[data-testid="retry-button"]').should('not.exist');

    // Verify data is displayed
    cy.get('[data-testid="data-table"]').should('be.visible');
    cy.get('[data-testid="data-row"]').should('have.length.greaterThan', 0);
  });
});
